<template><div class="space-y-6"><header><h1 class="text-2xl font-bold">Credit Cards</h1><p class="text-sm text-gray-500">Outstanding balances are included in liabilities and net worth.</p></header><div class="grid gap-4 sm:grid-cols-3"><StatCard label="Outstanding" :value="money(total)"/><StatCard label="Available credit" :value="money(available)"/><StatCard label="Overall utilization" :value="`${utilization.toFixed(1)}%`"/></div><p v-if="!cards.length" class="rounded-xl border bg-white p-6 text-sm text-gray-500">No credit-card accounts yet. Add an account with type Credit Card first.</p><div v-for="c in cards" :key="c.accountId" class="rounded-xl border bg-white p-5"><div class="flex justify-between"><div><h2 class="font-semibold">{{c.name}}</h2><p class="text-sm text-gray-500">{{c.institutionName}}</p></div><b>{{money(c.outstanding)}}</b></div><div class="mt-3 h-2 rounded bg-gray-200"><div class="h-2 rounded bg-indigo-600" :style="{width:`${Math.min(100,c.utilizationPct)}%`}"></div></div><div class="mt-4 grid gap-3 sm:grid-cols-4"><label class="text-xs">Statement day<input v-model.number="c.statementDay" min="1" max="31" type="number" class="mt-1 w-full rounded border-gray-300"></label><label class="text-xs">Due day<input v-model.number="c.paymentDueDay" min="1" max="31" type="number" class="mt-1 w-full rounded border-gray-300"></label><label class="text-xs">Total due<input v-model.number="c.totalAmountDue" min="0" type="number" class="mt-1 w-full rounded border-gray-300"></label><label class="text-xs">Interest %<input v-model.number="c.annualInterestRate" min="0" max="100" type="number" class="mt-1 w-full rounded border-gray-300"></label></div><button class="mt-3 text-sm font-medium text-indigo-700" @click="save(c)">Save statement details</button></div></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{creditCardsApi}from'../api/creditCards';import{formatMoney as money}from'../utils/formatters';import StatCard from'../components/StatCard.vue';const cards=ref([]),load=async()=>cards.value=(await creditCardsApi.list()).data?.data??[],save=async c=>{await creditCardsApi.save(c.accountId,c);await load()};const total=computed(()=>cards.value.reduce((s,x)=>s+Number(x.outstanding),0)),available=computed(()=>cards.value.reduce((s,x)=>s+Number(x.availableCredit),0)),limit=computed(()=>cards.value.reduce((s,x)=>s+Number(x.creditLimit),0)),utilization=computed(()=>limit.value?total.value/limit.value*100:0);onMounted(load)</script>
